scwin.sbm_selectQaChtStd01_submitdone = function(e) {
    var chartId = dmaQaChtStd01.get("chartId");
    var chtObj = {
        "dmaId": "dmaQaChtStd01", //차트설정맵
        "chartId": chartId, //그려질 퓨전차트ID
        "chartRefList": "data:dltQaResultChartList01", //그리기 위해 참조할 데이터리스트ID
        "avgRefList": "dltQaResultList01" //평균값 구하기 위한 리스트_커스트마이징
    }
    scwin.m_showColumnLineChart(chtObj);
};
