scwin.m_showColumnLineChart = function(obj) {
    var websqurelineChartId = WebSquare.wUnit.getObjById(obj.chartId);
    var websqureDmaId = WebSquare.wUnit.getObjById(obj.dmaId);
    var chartQaResultOption = {
        "caption": "탈지대두 품질 경향도 차트", //차트 제목
        //"subCaption" : "1월~ 기준월까지의 누적 데이터",				//차트 서브 제목
        //"xAxisName" : "날짜",				//x축 제목
        //"sYAxisName" : "total %",			//우측 y축 제목
        //"pYAxisName" : "설비효율",				//좌측 y축 제목
        //"numberPrefix" : "#",				//좌측 y축 데이터 앞에 문자 삽입
        //"numberSuffix" : obj.numberSuffix,//"", //좌측 y축 데이터 뒤에 문자 삽입
        //"sNumberPrefix" : "#",			//우측 y축 데이터 앞에 문자 삽입
        //"sNumberSuffix" : "%",			//우측 y축 데이터 뒤에 문자 삽입
        "showLegend": "0", //범례 표시(0, 1)
        "showValues": "1", //차트에 값 표시(0, 1)
        "showYAxisValues": "1", //y축 데이터값 표시 여부(0, 1)
        //"numDivlines" : splitCount, //y축 분할선 갯수 //입력 안하면 기본 4개
        //"yAxisValuesStep" : "2",			//y축 데이터값 표시 step 갯수 => 분할선 갯수가 아닌  step값 배수로 y축 표기//By default, all div lines show their values. However, you can opt to display every x(th) div line value using this attribute.
        //"yAxisMaxValue" : maximumValue, //라인 차트에서 사용하는 좌측 y축 데이터 최대값 파라미터
        //"yAxisMinValue" : minimumValue, //라인 차트에서 사용하는 좌측 y축 데이터 최대값
        //"pYAxisMaxValue" : "20",			//좌측 y축 데이터 최대값
        //"pYAxisMinValue" : "4",			//좌측 y축 데이터 최소값
        //"sYAxisMaxValue" : "100",			//우측 y축 데이터 최대값
        //"sYAxisMinValue" : "0",			//우측 y축 데이터 최소값
        "decimals": "2", //(좌측)number value 소수점자릿수 표시 (0~10)
        //"sDecimals" : "1",				//우측 데이터 소수점 자릿수 지정(0~10)
        //"showLabels" : "1",				//label 표시 여부(0, 1)
        //"labelStep" : "2",				//label 표시 step갯수
        "yAxisValueDecimals": "2", //(좌측)y축 데이터 소수점 자릿수 지정(0~10)
        //"sYAxisValueDecimals" : "1",		//우측 y축 데이터 소수점 자릿수 지정(0~10)
        //"showSum" : "1",					//stack 데이터 합계 표시(0, 1)
        //"legendPosition" : "right",		//범례 위치 지정(bottom, right)
        "useRoundEdges": "1", //디자인 엣지효과 적용 여부(0, 1)
        //"formatNumber" : "1",				//(좌측)number형식 표현 여부 ex.3,000 (0, 1)
        //"formatNumberScale" : "1",		//(좌측)number형식 단위 지정(0, 1 : 1043 will become 1.04K)
        //"sFormatNumber" : "1",			//우측 number형식 표현 여부 ex.3,000 (0,1)
        //"sFormatNumberScale" : "1",		//우측 number형식 단위 지정(0, 1 : 1043 will become 1.04K)
        "showHoverEffect": "1", //마우스 오버 이벤트 여부(0, 1) for all elements
        //"plotHoverEffect" : "1",			//마우스 오버 이벤트 여부(0, 1) for data plots
        //"plotFillHoverColor" : "#ffffff"	//데이터에 마우스 오버 시 색상 지정
    };
    console.log(obj.chartRefList);
    websqurelineChartId.options.seriesType = "";
    websqurelineChartId.changeType("MSLine"); //1. 차트 타입 지정(MSStackedColumn2DLineDY : MSstack 가로 & 선 차트)
    websqurelineChartId.setChartAttribute(chartQaResultOption);
    websqurelineChartId.setChartColumnRef(obj.chartRefList, 'yearMonth',
        "[['qaAvg']]");
    //websqurelineChartId.refresh();
    //활성화된 탭에서만 refresh()구문 동작
    //차트 3.7버전에서는 refresh 없어도 차트를 그리면 라인이 끊기는 현상이 없었음
};
scwin.tc_main_onchange = function(tabID, idx, userTabID) {
    //조회조건이 아니므로 dmasearch보다 전역변수 scwin.tabconfig로 처리
    if (idx == '0') { //증자수분
        scwin.tabconfig = 0;
        //cht_QMQR103_01.refresh();
    } else if (idx == '1') { //입국수분
        scwin.tabconfig = 1;
    } else if (idx == '2') { //출국수분
        scwin.tabconfig = 2;
    } else if (idx == '3') { //출국ph
        scwin.tabconfig = 3;
    } else if (idx == '4') { //역가
        scwin.tabconfig = 4;
    } else if (idx == '5') { //일반세균
        scwin.tabconfig = 5;
    } else if (idx == '6') { //산성세균
        scwin.tabconfig = 6;
    }
};
scwin.checkValue = function() {
    return document.getElementsByTagName('path')[4].getAttribute('d').split(",").length == 7;
}
scwin.unitTest = function() {
    //Init test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_search').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('tc_main_tab_tacpg03_tabHTML').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_search').click()");
    WebSquare.wUnit.addCommand("pause", "2000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('tc_main_tab_tacpg01_tabHTML').click()");
    WebSquare.wUnit.addCommand("pause", "2000");
    WebSquare.wUnit.addCommand("assert", "scwin.checkValue()", "true");
    //Run and Stop unit Test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

